/**
 * This function generate a plane at the top of the building with the desired text
 */
let generateLegend = (data, {
  name,
  scale,
  lookat,
  template = '{name}',
  colorPlane = 'white',
  colorText = 'black',
  isQuarter = false,
  fields = {}
}) => {
  const safe = (val, fallback = '') => typeof val !== 'undefined' ? val : fallback;
  const round = v => typeof v === 'number' ? Math.round(v * 100) / 100 : v;

  // Campos usados
  const fheight = fields.height || '';
  const farea = fields.area || '';
  const fwidth = fields.width || '';
  const fdepth = fields.depth || '';
  const fcolor = fields.color || '';

  // Datos correspondientes
  const vheight = round(safe(data?.[fheight]));
  const varea = round(safe(data?.[farea]));
  const vwidth = round(safe(data?.[fwidth]));
  const vdepth = round(safe(data?.[fdepth]));
  const vcolor = safe(data?.[fcolor]);

  // Texto final
  const finalText = isQuarter ? name : template.replaceAll('{name}', name)
  // nombres de los campos
  .replaceAll('{fheight}', fheight).replaceAll('{farea}', farea).replaceAll('{fwidth}', fwidth).replaceAll('{fdepth}', fdepth).replaceAll('{fcolor}', fcolor)
  // valores
  .replaceAll('{height}', vheight).replaceAll('{area}', varea).replaceAll('{width}', vwidth).replaceAll('{depth}', vdepth).replaceAll('{color}', vcolor);
  const lines = finalText.split('\n');
  const width = Math.max(...lines.map(line => line.length)) / 5;
  const height = lines.length * 0.3 + 0.3;
  const entity = document.createElement('a-plane');
  entity.setAttribute('babia-lookat', lookat);
  entity.setAttribute('rotation', {
    x: 0,
    y: 0,
    z: 0
  });
  entity.setAttribute('height', height);
  entity.setAttribute('width', width);
  entity.setAttribute('color', colorPlane);
  entity.setAttribute('material', {
    side: 'double'
  });
  entity.setAttribute('text', {
    value: finalText,
    align: 'center',
    width: 6,
    color: colorText,
    alphaTest: 6,
    opacity: 6,
    transparent: false
  });
  entity.setAttribute('visible', false);
  entity.setAttribute('class', 'babialegend');
  entity.setAttribute('scale', {
    x: scale,
    y: scale,
    z: scale
  });
  return entity;
};
function setOpacity(entity, opacity) {
  entity.setAttribute('material', 'opacity', opacity);
  if (entity.childNodes) {
    for (let i = 0; i < entity.childNodes.length; i++) {
      setOpacity(entity.childNodes[i], opacity);
    }
  }
}
let getLevels = (elements, levels) => {
  let level = levels;
  let max_level = levels;
  for (let i in elements) {
    if (elements[i].children) {
      level++;
      levels = getLevels(elements[i].children, level);
      if (max_level < levels) {
        max_level = levels;
      }
      level--;
    }
  }
  return max_level;
};
let getMaxMinValues = (data, field, valuesToAvg, max, min) => {
  for (let i = 0; i < data.length; i++) {
    if (data[i].children) {
      [max, min] = getMaxMinValues(data[i].children, field, valuesToAvg, max, min);
    } else {
      if (data[i][field] !== "null" && !max || data[i][field] > max) {
        max = data[i][field];
      }
      if (data[i][field] !== "null" && !(min !== undefined) || data[i][field] < min) {
        min = data[i][field];
      }
      valuesToAvg.push(data[i][field]);
    }
  }
  return [max, min, valuesToAvg];
};
function heatMapColorforValue(val, max, min) {
  //Blue to red
  let color2 = [19, 82, 138];
  let color1 = [255, 94, 83];
  let value = ((val || 0) - min) / (max - min);
  var p = value;
  var w = p * 2 - 1;
  var w1 = (w / 1 + 1) / 2;
  var w2 = 1 - w1;
  var rgb = [Math.round(color1[0] * w1 + color2[0] * w2), Math.round(color1[1] * w1 + color2[1] * w2), Math.round(color1[2] * w1 + color2[2] * w2)];
  return "rgb(" + rgb[0] + "," + rgb[1] + "," + rgb[2] + ")";
}
let findIndex = (list, condicion) => {
  condicion = condicion.split('=');
  //console.log(condicion)
  for (i = 0; i < list.length; i++) {
    if (list[i][condicion[0]] === condicion[1]) {
      return i;
    }
  }
  return -1;
};
let greenColorsurface = perc => {
  return "hsl(140, 100%," + perc + "%)";
};

